import 'package:aigammon_app/data/database.dart';
import 'package:drift/drift.dart' show Value;
import 'package:drift/native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:sqlite3/sqlite3.dart';

/// The exact v1 schema DDL (matches + games), as generated by drift at
/// schemaVersion 1 — before the v2 `settings` table existed. Embedded as a
/// constant so this test can materialise a genuine v1 database (raw sqlite3),
/// then open it through [AppDatabase] and prove the 1 -> 2 `onUpgrade` runs.
///
/// Column names/types mirror drift's output for the current `Matches`/`Games`
/// table definitions (unchanged across v1 -> v2), so v1 rows round-trip after
/// the upgrade.
const _v1MatchesDdl = '''
CREATE TABLE "matches" (
  "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
  "created_at" INTEGER NOT NULL,
  "match_length" INTEGER NOT NULL,
  "mode" TEXT NOT NULL,
  "white_type" TEXT NOT NULL,
  "black_type" TEXT NOT NULL,
  "white_score" INTEGER NOT NULL DEFAULT 0,
  "black_score" INTEGER NOT NULL DEFAULT 0,
  "winner" TEXT NULL,
  "completed" INTEGER NOT NULL DEFAULT 0 CHECK ("completed" IN (0, 1))
);
''';

const _v1GamesDdl = '''
CREATE TABLE "games" (
  "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
  "match_id" INTEGER NOT NULL REFERENCES matches (id) ON DELETE CASCADE,
  "game_number" INTEGER NOT NULL,
  "is_crawford" INTEGER NOT NULL CHECK ("is_crawford" IN (0, 1)),
  "events_json" TEXT NOT NULL,
  "result_winner" TEXT NULL,
  "result_points" INTEGER NULL,
  "result_outcome" TEXT NULL,
  "analysis_json" TEXT NULL
);
''';

void main() {
  test('1 -> 2 upgrade adds the settings table, seeds its default row, and '
      'preserves existing v1 data', () async {
    // 1. Build a genuine v1 database in a shared in-memory sqlite3 handle: the
    //    v1 tables, a real match row, and user_version = 1.
    final raw = sqlite3.openInMemory();
    raw.execute(_v1MatchesDdl);
    raw.execute(_v1GamesDdl);
    raw.execute(
      'INSERT INTO matches (created_at, match_length, mode, white_type, '
      "black_type) VALUES (1700000000, 5, 'vsComputer', 'human', 'ai:expert')",
    );
    raw.execute('PRAGMA user_version = 1');

    // Sanity: no settings table yet at v1.
    final before = raw.select(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='settings'");
    expect(before, isEmpty, reason: 'v1 has no settings table');

    // 2. Open the SAME database through AppDatabase (schemaVersion 2). drift
    //    sees user_version 1 and runs onUpgrade(1 -> 2), then beforeOpen.
    final db = AppDatabase(NativeDatabase.opened(raw));

    // 3a. The settings table now exists with the single default row.
    final settings = await db.select(db.settings).getSingle();
    expect(settings.id, 1);
    expect(settings.themeMode, 'system');
    expect(settings.animationSpeed, 'normal');
    expect(settings.defaultMatchLength, 5);
    expect(settings.defaultDifficulty, 'medium');
    expect(settings.tutorOverride, isNull);

    // 3b. The pre-migration v1 match row survived intact.
    final matches = await db.select(db.matches).get();
    expect(matches, hasLength(1));
    expect(matches.single.mode, 'vsComputer');
    expect(matches.single.matchLength, 5);
    expect(matches.single.whiteType, 'human');
    expect(matches.single.blackType, 'ai:expert');

    // 3c. The schema version was bumped to 2.
    final version = await db.customSelect('PRAGMA user_version').getSingle();
    expect(version.read<int>('user_version'), 2);

    // 3d. Writes still work post-migration (FK/insert into the migrated schema).
    final newId = await db.into(db.matches).insert(MatchesCompanion.insert(
          createdAt: DateTime.now(),
          matchLength: 3,
          mode: 'hotSeat',
          whiteType: 'human',
          blackType: 'human',
          whiteScore: const Value(0),
        ));
    expect(newId, greaterThan(matches.single.id));

    await db.close();
  });
}
